fields.InputDefinition:
{
  "goal": "Assume you are already logged in at http://localhost:4200. Open 'Bulk Operations', click 'New operation'. Build a minimal valid operation: type a Name (e.g. 'Test preview op'), select any Entity, then in the Rules section click 'Add rule', pick a target field, and give it a fixed value (leave source as 'a fixed value' and type something). Once 'Preview changes' is enabled, click it. A dry-run runner dialog should open showing a safe-preview message such as 'Computing a safe preview — no changes have been made yet…', then resolve to either a per-record diff preview (a summary like 'N of M will change' with an 'Apply … change(s)' button), a 'Nothing to change' empty state, or an error message about the preview. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away. Seeing the dry-run preview dialog open and resolve is success — you must NOT click Apply.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "Clicking 'Preview changes' opens the runner dialog with a safe-preview / 'no changes have been made yet' indication",
    "The dialog resolves to a preview outcome — a change summary with an 'Apply' action, a 'Nothing to change' state, or a clear error — without applying anything automatically",
    "No error messages, blank screens, or crash pages beyond an in-dialog preview error"
  ]
}
